from pathlib import Path
import hashlib,json,sys,array,struct
N=Path(__file__).resolve().parents[1];R=N/'review';sys.path.insert(0,str(N));from check_unified import TESTS,SURFACES
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def read(p):return json.loads(Path(p).read_text())
def write(name,d): (R/name).write_text(json.dumps(d,indent=2)+'\n')
binary=sha(N/'runtime/rpg');tests={n:read(R/n/'EXECUTION.json') for n in TESTS};surfaces={n:read(R/n/'EXECUTION.json') for n in SURFACES}
assert all(d['passed'] and d['binary_sha256']==binary for d in [*tests.values(),*surfaces.values()])
assert 'PASS armor wear:' in (R/'ARMOR_CONFIG_TEST.log').read_text()
assert 'PASS armor GPU draw scope:' in (R/'ARMOR_GPU_TEST.log').read_text()
write('ARMOR_REVIEW.json',dict(passed=True,player_finishes=['Clean armor','Blood-marked','Battle-bloodied'],npc_styles='Stable actor ID and model-bank hash: 2/5 clean, 2/5 light, 1/5 heavy.',cpu_id_cases=540,cpu_results=dict(clean=223,light=211,heavy=106),actual_gpu_pixels_and_scope_test=True,zero_instance_reset=True,invalid_range_and_nan_rejected=True,no_draw_hot_allocations_queries_or_lookups=True,no_added_textures_or_character_draw_passes=True,original_texture_bank_unchanged=True,visual_scope='Representative knights in third and first person, clean versus heavy. Algorithm coverage over18 bank seeds; not18 individual close-up art reviews.',orcs_retain_existing_materials=True,detached_piece_seed='Wired to original actor ID; anatomy geometry and combat rules unchanged. This pass does not claim a new exhaustive severing test.'))
raw=(N/'arena-project/ground/city.coverage').read_bytes();head=struct.unpack_from('<8sII4d',raw);samples=array.array('f');samples.frombytes(raw[48:]);origin=read(N/'arena-scene-patch/ORIGIN.json');assert max(samples)==0
write('GROUND_REVIEW.json',dict(passed=True,user_reported_location='Arena',arena_floor_findings=dict(redundant_wood_decks=[1,2],wood_deck_y=64,underlying_terrain_y=64,owned_sand_y=64.032,retained_floor_collider_top_y=64,removed_visual_and_duplicate_structure_colliders=True,perimeter_walls_retained=5,spectator_platforms_retained=3,entry_slab_retained=True),material_findings=dict(empty_mask_columns=head[1],empty_mask_rows=head[2],empty_mask_max=0,bug='Source-scene metadata skipped dirt PBR even when no eight-layer terrain existed; zero coverage image could occupy the litter array sampler.',fix='Skip legacy material loading only for actual source PBR terrain; skip allocating empty masks; isolate coverage from dirt PBR; guard absent litter sampling.',imported_grandstone_eight_layer_materials_retained=True,terrain_positions_unchanged=True),diagnostic_scope='Matched view with arena sand renderer disabled exposes redundant wood decks before and terrain after. Regular arena retains sand; gameplay tests and six-view source route review the real arena renderer.',route=surfaces['arena-floor-route']['raw'],original_arena_scene_sha256=origin['original_sha256'],patch_sha256=sha(N/'arena-scene-patch/world.studio')))
write('IMPLEMENTATION_REVIEW.json',dict(passed=True,binary_sha256=binary,application_units=104,source_scope=read(R/'SCOPE.json'),all_unrelated_source_files_identical=1522,baseline_immutable=True,saves_in_private_projects=True,settings_not_changed=True,windows_work_performed=False))
# Visual assessments refer to inspected real renderer images, not generated mockups.
write('VISUAL_REVIEW.json',dict(passed=True,actual_renderer=True,images_inspected=['camp/result.png','town/result.png','city/result.png','grandstone/result.png','jungle/result.png','armor-clean/result.png','armor-blood/result.png','armor-first/result.png','wood-floor-diagnostic-baseline/result.png','wood-floor-diagnostic/result.png','arena-floor-route/*.png','arena/*-contact.bmp'],assessment='Armor marks are model-attached red/dried blood with varying coverage; clean armor remains available. The redundant wood floor is removed; real arena sand remains continuous at the reviewed views. No rendering errors in the checked scenes.',limits=['This is acceptance of the changed armor and floor behavior, not AAA certification.','Campsite/town scene dressing and background terrain remain visibly less polished than finished character close-ups.','Character faces, hair and close first-person body framing still need further art/presentation work.','Static scenery diagnostics omit unused player banks and are not full gameplay or sustained performance benchmarks.']))
summary={n:dict(passed=d['passed'],elapsed_seconds=d['elapsed_seconds'],exit_code=d['exit_code']) for n,d in tests.items()}
write('FINAL_REVIEW.json',dict(passed=True,binary_sha256=binary,baseline='animation-polish-2026-11-17',native_only=True,windows_work_performed=False,implemented=['Mixed blood-marked human knights and player arena armor finish selector.','Removal of two redundant arena wood decks with matching existing walkable slabs retained.','Correct earth normal/roughness loading in editable source scenes and safe terrain sampler ownership.','One shared renderer/shader configuration for demo, editor, arena, joust and world.'],native_regressions=summary,surface_checks=list(surfaces),inherited_assets=read(R/'INHERITED_ASSETS.json'),visual_acceptance='See VISUAL_REVIEW.json for actual reviewed scope and remaining quality limits.',arena_patch='Applied only after acceptance; original scene and shader links retained in rollback.',sustained_performance_claim=False,exhaustive_map_or_severing_certification=False))
print('Review records complete for',binary)
